 "decisions": [
  {
   "title": "One transaction per transfer",
   "context": "The legacy opens a SqlTransaction, rolls back explicitly on every rejection and commits after the insert.",
   "decision": "RealizarTransferencia runs in a single @Transactional boundary. Business rejections are exceptions that roll the transaction back. The success path commits once, after debit, credit and insert.",
   "consequences": "Same atomicity as the legacy. The explicit Rollback calls and the lblMensaje assignments are replaced by exceptions mapped to HTTP 422 with the stable code and the legacy message text. The rejection checks run before any write."
  },
  {
   "title": "Commission is a pure domain calculation",
   "context": "ComisionService.Calcular is a static helper used only by the transfer page (RULE-001 to RULE-003).",
   "decision": "The calculation becomes a domain component without ports, using BigDecimal. Order: base fee (0.50 if monto <= 1000.00, else monto*0.001 rounded to 2 decimals with RoundingMode.HALF_UP, which is away from zero for the positive amounts here), then cap at 5.00, then +1.00 when tipo equals \"INM\" (case-sensitive). RealizarTransferencia calls it. It has no endpoint of its own.",
   "consequences": "An INM commission can reach 6.00. The calculation is covered by unit tests with the rule scenarios and is replayed through the TRANSFERENCIA traces."
  },
  {
   "title": "Legacy column precision kept",
   "context": "The rules describe money as decimal(19,4), but the legacy tables use DECIMAL(13,2) for balances, DECIMAL(11,2) for amounts and DECIMAL(7,2) for commissions.",
   "decision": "Entities and port inputs use the precision of the legacy columns. The amount input is decimal(11,2), and balance updates are database-side (saldo = saldo +/- valor).",
   "consequences": "No change in stored values. An amount with more than two decimals is rejected at the API boundary (HTTP 400). The legacy would have rounded it silently on insert."
  },
  {
   "title": "Next transfer number kept as MAX+1, with a row lock on the origin",
   "context": "The legacy reads the balance without a lock and computes the number with ISNULL(MAX(TRF_NUMERO),0)+1, which is racy under concurrency.",
   "decision": "The numbering rule is kept (RULE-009) and is read inside the same transaction. The origin account is read with a row lock (findByNumeroForUpdate), so the balance check and the debit are consistent. The primary key still forbids duplicate numbers.",
   "consequences": "Sequential behaviour is identical to the legacy and to the traces. Under concurrency, a primary-key collision or a deadlock victim returns HTTP 409 and the client may retry. This only differs from the legacy in cases where the legacy could produce duplicate-key errors or an overdraft."
  },
  {
   "title": "Page validators move to the API boundary",
   "context": "Transferencia.aspx has validators: origin required and 10 digits, destination required, amount required and between 1 and 10000, and a dropdown that only allows PRO or INM. They are not business rules. int.Parse in Comprobante throws an unhandled error on a bad number.",
   "decision": "Bean Validation on the request reproduces these checks and returns HTTP 400 with no business error code. The type must be PRO or INM. A non-numeric receipt number is also an HTTP 400.",
   "consequences": "Requests that the legacy page would block (or that crashed it) are rejected before the use case. The business rules are unchanged. The traces only contain inputs that pass these validations."
  },
  {
   "title": "Receipt formatting and replay coverage",
   "context": "RULE-004 requires the amount as text with two decimals, blank if the transfer does not exist. There is no trace of the Comprobante page.",
   "decision": "ConsultarComprobante returns numero and monto as text (monto formatted '0.00', empty string when not found) and responds 200 in both cases. The commission of the transfer response is also text formatted '0.00' (lblComision).",
   "consequences": "Text outputs keep trailing zeros, which a JSON number would lose. RULE-004 is verified only by its scenarios, not by golden master replay."
  },
  {
   "title": "Configuration and presentation are replaced",
   "context": "Web.config holds the connection string with integrated security. The .aspx pages, the redirect to Comprobante.aspx and Page_Load only handle UI.",
   "decision": "The datasource is configured through the Spring configuration and secrets of the platform. The POST response returns numero and the client navigates to the receipt. Page_Load, which only clears lblMensaje, is not translated.",
   "consequences": "No UI behaviour is migrated. Legacy-visible outputs are exposed as response fields."
  }
 ],
 "masks": [],
 "infrastructure": [
  "Transferencia.Page_Load"
 ]
}

